interface UpdateBookDTO {
  readonly title?: string;
  readonly stock?: number;
}

function parseUpdateBook(body: Record<string, unknown>): UpdateBookDTO {
  const issues: string[] = [];
  for (const key of Object.keys(body)) {
    if (key !== "title" && key !== "stock") issues.push(`${key} cannot be set`);
  }
  const dto: { title?: string; stock?: number } = {};
  if ("title" in body) {
    const title = body["title"];
    if (typeof title === "string" && title.trim() !== "") dto.title = title.trim();
    else issues.push("title must be text");
  }
  if ("stock" in body) {
    const stock = body["stock"];
    if (typeof stock === "number" && Number.isSafeInteger(stock) && stock >= 0 && stock <= 10000) dto.stock = stock;
    else issues.push("stock must be 0 to 10000");
  }
  if (issues.length > 0) throw new Error(issues.join("; "));
  return dto;
}

for (const body of [{ stock: 4 }, { id: 7, stock: -1 }]) {
  try {
    console.log(JSON.stringify(parseUpdateBook(body)));
  } catch (error) {
    console.log(error instanceof Error ? error.message : error);
  }
}

