type Role = "customer" | "admin";
type Action = "book:create" | "order:read-own";
interface Principal { readonly userId: number; readonly role: Role }

const GRANTS: Readonly<Record<Role, readonly Action[]>> = {
  customer: ["order:read-own"],
  admin: ["book:create", "order:read-own"],
};

function authorize(principal: Principal | undefined, action: Action): Principal {
  if (principal === undefined) throw new Error("unauthenticated");
  if (!GRANTS[principal.role].includes(action)) throw new Error(`forbidden: ${action}`);
  return principal;
}

const attempts: [Principal | undefined, Action][] = [
  [{ userId: 1, role: "admin" }, "book:create"],
  [{ userId: 2, role: "customer" }, "book:create"],
  [undefined, "order:read-own"],
];
for (const [principal, action] of attempts) {
  try {
    console.log("allowed for user", authorize(principal, action).userId);
  } catch (error) {
    console.log(error instanceof Error ? error.message : error);
  }
}

