interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
}

function toPage<T>(rows: readonly T[], limit: number, idOf: (item: T) => number): Page<T> {
  const items = rows.slice(0, limit);
  const last = items.at(-1);
  const nextCursor = rows.length > limit && last !== undefined ? `after:${idOf(last)}` : null;
  return { items, nextCursor };
}

