interface Book { readonly id: number; readonly title: string; readonly stock: number }

interface BookRepository {
  create(book: Omit<Book, "id">): Promise<Book>;
  findById(id: number): Promise<Book | undefined>;
}

class MemoryBookRepository implements BookRepository {
  private readonly books: Book[] = [];

  async create(book: Omit<Book, "id">): Promise<Book> {
    const saved = { ...book, id: this.books.length + 1 };
    this.books.push(saved);
    return saved;
  }

  async findById(id: number): Promise<Book | undefined> {
    return this.books.find((book) => book.id === id);
  }
}

async function restock(books: BookRepository, id: number): Promise<string> {
  const book = await books.findById(id);
  return book === undefined ? `book ${id} not found` : `${book.title}: ${book.stock} in stock`;
}

const repository = new MemoryBookRepository();
await repository.create({ title: "Kindred", stock: 4 });
console.log(await restock(repository, 1));
console.log(await restock(repository, 2));
